                    return int(v["x"]), int(v["y"])
                if 0 in v and 1 in v:
                    return int(v[0]), int(v[1])
            except:
                return None
        return None

    def pts(v):
        r = []
        if isinstance(v, (list, tuple)):
            for a in v:
                p = pos(a)
                if p is not None:
                    r.append(p)
        return r

    w = int(g.get("grid_width", 0) or 0)
    h = int(g.get("grid_height", 0) or 0)
    s = pos(g.get("self_position")) or pos(g.get("agent_position")) or (0, 0)
    o = pos(g.get("opponent_position")) or pos(g.get("enemy_position"))

    blocked = set(pts(g.get("obstacles")))
    for k in ("self_path", "opponent_path", "path", "trail", "visited"):
